  private productsSubject = new BehaviorSubject<Product[]>(this.mockProducts);

  constructor(private http: HttpClient) {}

  getProducts(): Observable<Product[]> {
    // Real API: return this.http.get<Product[]>(this.apiUrl);
    return this.productsSubject.asObservable();
  }

  getProduct(id: number): Observable<Product | undefined> {
    // Real API: return this.http.get<Product>(`${this.apiUrl}/${id}`);
    return of(this.productsSubject.value.find(p => p.id === id));
  }

  addProduct(product: Omit<Product, 'id'>): Observable<Product> {
    // Real API: return this.http.post<Product>(this.apiUrl, product);
    const newProduct = { ...product, id: Date.now() };
    this.productsSubject.next([...this.productsSubject.value, newProduct]);
    return of(newProduct);
  }

  updateProduct(id: number, product: Product): Observable<Product> {
    // Real API: return this.http.put<Product>(`${this.apiUrl}/${id}`, product);
    const updated = this.productsSubject.value.map(p => p.id === id ? product : p);
    this.productsSubject.next(updated);
    return of(product);
  }

  deleteProduct(id: number): Observable<void> {
    // Real API: return this.http.delete<void>(`${this.apiUrl}/${id}`);
    this.productsSubject.next(this.productsSubject.value.filter(p => p.id !== id));
    return of(undefined);
  }
}
